class ObjectManipulation:
    def time_manipulation(self, library, geometry, operation):
        if operation == "Translate":
            for _ in range(10000):
                self.move_by((0.001, 0.002, 0.003))
        elif operation == "Rotate":
            if library == "PyMagba":
                rot_quat = self.rot.as_quat()
                for _ in range(10000):
                    self.rotate_by(rot_quat)
            else:
                for _ in range(10000):
                    self.rotate_by(self.rot)

    def setup(self, library, geometry, operation):
        self.rot = Rotation.from_euler("xyz", [10, 20, 30], degrees=True)
        if library == "PyMagba":
            if geometry == "Cylinder":
                self.magnet = pymagba.magnets.CylinderMagnet(
                    position=(0, 0, 0),
                    orientation=get_standard_rotation(),
                    diameter=0.1,
                    height=0.2,
                    polarization=(1, 2, 3),
                )
            elif geometry == "Collection":
                m1 = pymagba.magnets.CylinderMagnet(
                    position=(0.005, 0.0, 0.0),
                    diameter=0.01,
                    height=0.02,
                    polarization=(0.0, 0.0, 1.0),
                )
                m2 = pymagba.magnets.CuboidMagnet(
                    position=(-0.005, 0.0, 0.0),
                    dimensions=(0.01, 0.01, 0.01),
                    polarization=(0.0, 0.0, -1.0),
                )
                self.magnet = pymagba.magnets.SourceCollection([m1, m2])

            self.move_by = self.magnet.translate  # type: ignore
            self.rotate_by = self.magnet.rotate
        else:
            if geometry == "Cylinder":
                self.magnet = Cylinder(
                    position=(0, 0, 0),
                    orientation=get_standard_rotation(),
                    dimension=(0.1, 0.2),
                    polarization=(1, 2, 3),
                )
            elif geometry == "Collection":
                m1 = Cylinder(
                    position=(0.005, 0.0, 0.0),
                    dimension=(0.01, 0.02),
                    polarization=(0.0, 0.0, 1.0),
                )
                m2 = Cuboid(
                    position=(-0.005, 0.0, 0.0),
                    dimension=(0.01, 0.01, 0.01),
                    polarization=(0.0, 0.0, -1.0),
                )
                self.magnet = MagpyCollection(m1, m2)

            self.move_by = self.magnet.move  # type: ignore
            self.rotate_by = self.magnet.rotate
